-- Fase 3B: catÃ¡logo acadÃ©mico persistente, entregas internas y almacenamiento privado.
-- Ejecutar despuÃ©s de 20260923000000_phase2_courses_enrollments.sql.

create table public.activities (
  id text primary key check (id ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'),
  course_id uuid not null references public.courses(id) on delete restrict,
  module_number smallint not null check (module_number > 0),
  title text not null check (char_length(trim(title)) between 2 and 240),
  activity_type text not null check (activity_type in ('exercise', 'assignment', 'challenge', 'mini_project', 'project', 'final_project')),
  required boolean not null default true,
  display_order smallint not null check (display_order > 0),
  status text not null default 'active' check (status in ('active', 'archived')),
  original_max_points numeric(8,2) not null check (original_max_points > 0),
  normalized_max_points numeric(8,2) not null default 100 check (normalized_max_points = 100),
  max_files smallint not null default 1 check (max_files = 1),
  max_file_size_bytes integer not null default 10485760 check (max_file_size_bytes = 10485760),
  allowed_file_types text[],
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (course_id, module_number, display_order)
);

create table public.rubrics (
  id uuid primary key default gen_random_uuid(),
  activity_id text not null unique references public.activities(id) on delete cascade,
  source_kind text not null check (source_kind in ('new', 'existing')),
  canonical_source text,
  original_max_points numeric(8,2) not null check (original_max_points > 0),
  normalized_max_points numeric(8,2) not null default 100 check (normalized_max_points = 100),
  created_at timestamptz not null default now()
);

create table public.rubric_criteria (
  id uuid primary key default gen_random_uuid(),
  rubric_id uuid not null references public.rubrics(id) on delete cascade,
  label text not null check (char_length(trim(label)) between 2 and 240),
  description text,
  max_points numeric(8,2) not null check (max_points > 0),
  display_order smallint not null check (display_order > 0),
  unique (rubric_id, display_order)
);

create table public.submissions (
  id uuid primary key default gen_random_uuid(),
  student_id uuid not null references public.profiles(id) on delete restrict,
  course_id uuid not null references public.courses(id) on delete restrict,
  activity_id text not null references public.activities(id) on delete restrict,
  status text not null default 'submitted' check (status in ('submitted', 'reviewed')),
  submitted_at timestamptz not null default now(),
  storage_path text unique,
  original_filename text check (original_filename is null or char_length(original_filename) between 1 and 255),
  stored_filename text,
  file_size integer check (file_size is null or file_size between 1 and 10485760),
  mime_type text,
  grade numeric(5,2) check (grade is null or grade between 0 and 100),
  feedback text,
  reviewed_at timestamptz,
  reviewed_by uuid references public.profiles(id) on delete set null,
  convalidated boolean not null default false,
  convalidation_note text,
  file_deleted_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (student_id, activity_id)
);

create index activities_course_module_idx on public.activities(course_id, module_number);
create index submissions_course_idx on public.submissions(course_id, submitted_at desc);
create index submissions_student_idx on public.submissions(student_id, submitted_at desc);

alter table public.activities enable row level security;
alter table public.rubrics enable row level security;
alter table public.rubric_criteria enable row level security;
alter table public.submissions enable row level security;

create policy "activities_enrolled_or_admin_read" on public.activities for select to authenticated using (
  (select public.is_admin()) or exists (
    select 1 from public.enrollments e
    where e.course_id = activities.course_id and e.student_id = (select auth.uid()) and e.status = 'active'
  )
);
create policy "activities_admin_manage" on public.activities for all to authenticated using ((select public.is_admin())) with check ((select public.is_admin()));
create policy "rubrics_enrolled_or_admin_read" on public.rubrics for select to authenticated using (
  (select public.is_admin()) or exists (
    select 1 from public.activities a join public.enrollments e on e.course_id = a.course_id
    where a.id = rubrics.activity_id and e.student_id = (select auth.uid()) and e.status = 'active'
  )
);
create policy "rubrics_admin_manage" on public.rubrics for all to authenticated using ((select public.is_admin())) with check ((select public.is_admin()));
create policy "criteria_enrolled_or_admin_read" on public.rubric_criteria for select to authenticated using (
  (select public.is_admin()) or exists (
    select 1 from public.rubrics r join public.activities a on a.id = r.activity_id join public.enrollments e on e.course_id = a.course_id
    where r.id = rubric_criteria.rubric_id and e.student_id = (select auth.uid()) and e.status = 'active'
  )
);
create policy "criteria_admin_manage" on public.rubric_criteria for all to authenticated using ((select public.is_admin())) with check ((select public.is_admin()));
create policy "submissions_own_or_admin_read" on public.submissions for select to authenticated using (student_id = (select auth.uid()) or (select public.is_admin()));
create policy "submissions_admin_manage" on public.submissions for all to authenticated using ((select public.is_admin())) with check ((select public.is_admin()));

revoke all on public.activities, public.rubrics, public.rubric_criteria, public.submissions from anon, authenticated;
grant select on public.activities, public.rubrics, public.rubric_criteria, public.submissions to authenticated;
grant insert, update, delete on public.activities, public.rubrics, public.rubric_criteria, public.submissions to authenticated;

create trigger activities_set_updated_at before update on public.activities for each row execute procedure public.set_profile_updated_at();
create trigger submissions_set_updated_at before update on public.submissions for each row execute procedure public.set_profile_updated_at();

create or replace function public.upsert_submission_metadata(
  p_activity_id text, p_storage_path text, p_original_filename text, p_stored_filename text,
  p_file_size integer, p_mime_type text
) returns table (submission_id uuid, old_storage_path text, submitted_at timestamptz)
language plpgsql security definer set search_path = '' as $$
declare
  v_user_id uuid := auth.uid();
  v_course_id uuid;
  v_old_path text;
  v_submission_id uuid;
  v_submitted_at timestamptz;
begin
  if v_user_id is null then raise exception 'authentication required'; end if;
  if p_file_size < 1 or p_file_size > 10485760 then raise exception 'invalid file size'; end if;
  if char_length(p_original_filename) not between 1 and 255 then raise exception 'invalid filename'; end if;
  if p_storage_path <> (v_user_id::text || '/' || p_activity_id || '/submission') then raise exception 'invalid storage path'; end if;

  select a.course_id into v_course_id from public.activities a
  where a.id = p_activity_id and a.status = 'active' and a.max_files = 1 and p_file_size <= a.max_file_size_bytes;
  if v_course_id is null then raise exception 'activity unavailable'; end if;
  if not exists (select 1 from public.profiles p where p.id = v_user_id and p.role = 'student') then raise exception 'student required'; end if;
  if not exists (select 1 from public.enrollments e where e.student_id = v_user_id and e.course_id = v_course_id and e.status = 'active') then raise exception 'active enrollment required'; end if;

  select s.storage_path into v_old_path from public.submissions s where s.student_id = v_user_id and s.activity_id = p_activity_id for update;
  values (v_user_id, v_course_id, p_activity_id, 'submitted', now(), p_storage_path, p_original_filename, p_stored_filename, p_file_size, p_mime_type, null)
  on conflict (student_id, activity_id) do update set
    course_id = excluded.course_id, status = 'submitted', submitted_at = excluded.submitted_at,
    storage_path = excluded.storage_path, original_filename = excluded.original_filename,
    stored_filename = excluded.stored_filename, file_size = excluded.file_size, mime_type = excluded.mime_type,
    file_deleted_at = null, updated_at = now()
  returning id, public.submissions.submitted_at into v_submission_id, v_submitted_at;
  return query select v_submission_id, v_old_path, v_submitted_at;
end;
$$;
revoke all on function public.upsert_submission_metadata(text, text, text, text, integer, text) from public, anon;
grant execute on function public.upsert_submission_metadata(text, text, text, text, integer, text) to authenticated;

values ('academic-submissions', 'academic-submissions', false, 10485760, null)
on conflict (id) do update set public = false, file_size_limit = 10485760, allowed_mime_types = null;

create policy "academic_files_student_insert" on storage.objects for insert to authenticated with check (
  bucket_id = 'academic-submissions' and (storage.foldername(name))[1] = (select auth.uid())::text
  and name = ((select auth.uid())::text || '/' || (storage.foldername(name))[2] || '/submission')
  and exists (select 1 from public.activities a join public.enrollments e on e.course_id = a.course_id
    where a.id = (storage.foldername(name))[2] and a.status = 'active' and e.student_id = (select auth.uid()) and e.status = 'active')
);
create policy "academic_files_own_or_admin_read" on storage.objects for select to authenticated using (
  bucket_id = 'academic-submissions' and (
    ((storage.foldername(name))[1] = (select auth.uid())::text and name = ((select auth.uid())::text || '/' || (storage.foldername(name))[2] || '/submission'))
    or (select public.is_admin())
  )
);
create policy "academic_files_student_update" on storage.objects for update to authenticated using (
  bucket_id = 'academic-submissions' and (storage.foldername(name))[1] = (select auth.uid())::text
  and name = ((select auth.uid())::text || '/' || (storage.foldername(name))[2] || '/submission')
) with check (
  bucket_id = 'academic-submissions' and (storage.foldername(name))[1] = (select auth.uid())::text
  and name = ((select auth.uid())::text || '/' || (storage.foldername(name))[2] || '/submission')
  and exists (select 1 from public.activities a join public.enrollments e on e.course_id = a.course_id
    where a.id = (storage.foldername(name))[2] and a.status = 'active' and e.student_id = (select auth.uid()) and e.status = 'active')
);
create policy "academic_files_own_delete" on storage.objects for delete to authenticated using (
  bucket_id = 'academic-submissions' and (
    ((storage.foldername(name))[1] = (select auth.uid())::text and name = ((select auth.uid())::text || '/' || (storage.foldername(name))[2] || '/submission'))
    or (select public.is_admin())
  )
);

